import round10f = require( './index' );

// TESTS //

// The function returns a number...
{
	round10f( 8.78, 2 ); // $ExpectType number
	round10f( 8.78, 0 ); // $ExpectType number
	round10f( 8.78, -2 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument other than a number...
{
	round10f( true, 1 ); // $ExpectError
	round10f( false, 1 ); // $ExpectError
	round10f( null, 1 ); // $ExpectError
	round10f( undefined, 1 ); // $ExpectError
	round10f( '5', 1 ); // $ExpectError
	round10f( [], 1 ); // $ExpectError
	round10f( {}, 1 ); // $ExpectError
	round10f( ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument other than a number...
{
	round10f( 3.14, true ); // $ExpectError
	round10f( 3.14, false ); // $ExpectError
	round10f( 3.14, null ); // $ExpectError
	round10f( 3.14, undefined ); // $ExpectError
	round10f( 3.14, '5' ); // $ExpectError
	round10f( 3.14, [] ); // $ExpectError
	round10f( 3.14, {} ); // $ExpectError
	round10f( 3.14, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided insufficient arguments...
{
	round10f(); // $ExpectError
	round10f( 3.14 ); // $ExpectError
}
